for s in (1234,42,2025):
 d=[next(x for x in rows if (x['fold'],x['seed'],x['arm'])==(f,s,'dynamic'))['metrics']['macro_f1'] for f in range(5)];a=[next(x for x in rows if (x['fold'],x['seed'],x['arm'])==(f,s,'static'))['metrics']['macro_f1'] for f in range(5)];lines.append('| %d | %.4f ± %.4f | %.4f ± %.4f | %+.4f |'%(s,statistics.mean(d),statistics.stdev(d),statistics.mean(a),statistics.stdev(a),statistics.mean(x-y for x,y in zip(d,a))))
